            print(n, pyi.signature(f))
        except Exception as e:
            print(n, 'ERR', e)
        d = (f.__doc__ or '').strip()
        print('   ', d[:900].replace('\n','\n    '))
        print('---')

def run(_context):
    import json
    print(json.dumps(mb.inspect(), indent=1)[:3000])
