            pr = s.parameters.itemByName(p)
            print(p, pr.expression if pr else None)
        except Exception as e:
            print(p, 'ERR', e)
    print('---tools---')
    for t in mb.list_library_tools(contains='TIW', limit=300):
        print(t)

